head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
scwin.nSeq = 0;

scwin.logEvent = function (strName, rowIndex, colIndex) {
    scwin.nSeq = scwin.nSeq + 1;
    scwin.setReturnValue("[" + scwin.nSeq + "] " + strName + " 발생 (rowIndex : " + rowIndex + " / colIndex : " + colIndex + ")");
};

scwin.target1_onyearselect = function (rowIndex, colIndex, info) {
    scwin.logEvent("onyearselect", rowIndex, colIndex);
};

scwin.target1_onmonthselect = function (rowIndex, colIndex, info) {
    scwin.logEvent("onmonthselect", rowIndex, colIndex);
};

scwin.target1_ondateselect = function (rowIndex, colIndex, date, dateObject) {
    scwin.logEvent("ondateselect", rowIndex, colIndex);
};
